package com.tamo.service;
import com.google.gson.*;
import com.tamo.model.*;
import com.tamo.model.Module;
import com.tamo.util.JsonUtil;
import java.util.*;
import java.time.*;
import java.util.regex.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
/** Validates every row on a detached model, then commits the whole import in the API transaction. */
public class SponsorCsvService {
 public static final List<String> STUDENTS=List.of("First Name","Last Name","UCI Email","UCI Student ID","Student Level","Academic Program","Year Started Graduate Program","Faculty/PI","Total TA Quarters at UCI","Advanced to Candidacy","Completed TA Training","Completed Online Sexual Harassment Training","Additional On-Campus Employment","Documented Accommodation (DSC)","Ack: Schedule Conflict Check","Ack: Full-Time Enrollment & Fees","Skills & Experience","Courses of Interest","Scheduling Conflicts","Testing Scenario / Purpose");
 public static final List<String> COURSES=List.of("Course ID","Course Name","Section Type","Section Schedule (Days/Time)","Positions Needed","Required Skills","Preferred Skills");
 public static final List<String> SELECTIONS=List.of("First Name","Last Name","Proposed Course & Section","Match Status","Conflict/Eligibility Notes","Selection Status","Responsible User","Export Roster Preview");
 private final JsonDataService data;private static final byte[] TOKEN_KEY=new byte[32];static{new SecureRandom().nextBytes(TOKEN_KEY);}
 public SponsorCsvService(JsonDataService data){this.data=data;}
 public static List<String> headers(String dataset){if(dataset==null)throw problem("Choose a dataset.");return switch(dataset){case "students"->STUDENTS;case "courses"->COURSES;case "selections"->SELECTIONS;default->throw problem("Choose students, courses or selections.");};}
 private static QualificationService.Problem problem(String message){return new QualificationService.Problem(400,message);}
 private static String id(String prefix){return prefix+UUID.randomUUID().toString().replace("-","");}
 private static String now(){return Instant.now().toString();}
 private static String text(JsonObject b,String key){return b.has(key)&&!b.get(key).isJsonNull()?b.get(key).getAsString():"";}
 private static String need(Map<String,String> row,String key){String v=row.get(key);if(v==null||v.isBlank())throw problem(key+" is required.");return v;}
 private static List<String> split(String v){if(v.isBlank())return new ArrayList<>();return Arrays.stream(v.split(",")).map(String::trim).filter(s->!s.isEmpty()).distinct().toList();}
 private static boolean yes(String s){if(s.equalsIgnoreCase("Yes"))return true;if(s.equalsIgnoreCase("No"))return false;throw problem("Expected Yes or No, received: "+s);}
 private static String norm(String s){return s.toLowerCase(Locale.ROOT).replaceAll("\\bsection\\b", "").replaceAll("[^a-z0-9]","");}
 private String token(String actor,JsonObject body){try{JsonObject request=body.deepCopy();request.remove("previewToken");JsonObject state=JsonUtil.getGson().toJsonTree(data.getData()).getAsJsonObject();state.remove("logs");state.remove("notifications");Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(TOKEN_KEY,"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal((actor+request+state).getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 private static ApplicationPeriod period(DataStore ds,String id){return ds.getApplicationPeriods().stream().filter(p->id.equals(p.getId())&&!p.getLegacy()).findFirst().orElseThrow(()->problem("Choose a non-historical application cycle."));}
 public JsonObject run(String actor,JsonObject body,boolean commit){
  User user=ReviewAccess.user(data.getData(),actor);String kind=text(body,"dataset");headers(kind);
  if(!"admin".equals(user.getRole())&&!("organiser".equals(user.getRole())&&"courses".equals(kind)))throw new QualificationService.Problem(403,"Only administrators import student/selection data; organisers may import their own courses.");
  String stamp=token(actor,body);if(commit&&!MessageDigest.isEqual(stamp.getBytes(StandardCharsets.UTF_8),text(body,"previewToken").getBytes(StandardCharsets.UTF_8)))throw new QualificationService.Problem(409,"Preview is missing or data changed. Preview the file again.");
  DataStore ds=JsonUtil.getGson().fromJson(JsonUtil.getGson().toJson(data.getData()),DataStore.class);JsonDataService detached=JsonDataService.detached(ds);ApplicationPeriod p=period(ds,text(body,"periodId"));
  List<Map<String,String>> rows=SponsorCsv.read(text(body,"csv"),headers(kind));JsonArray results=new JsonArray();int errors=0,created=0,skipped=0;
  for(int i=0;i<rows.size();i++){JsonObject result=new JsonObject();result.addProperty("row",i+2);Map<String,String> input=rows.get(i);String summary="courses".equals(kind)?input.get("Course ID")+" · "+input.get("Section Type")+" · "+input.get("Section Schedule (Days/Time)"):input.get("First Name")+" "+input.get("Last Name")+" · "+("students".equals(kind)?input.get("UCI Email")+" · "+input.get("Courses of Interest"):input.get("Proposed Course & Section")+" · "+input.get("Selection Status"));result.addProperty("summary",summary);try{String outcome=switch(kind){case "courses"->course(detached,user,body,p,rows.get(i));case "students"->student(detached,p,rows.get(i));default->selection(detached,user,p,rows.get(i));};result.addProperty("status",outcome);if("unchanged".equals(outcome))skipped++;else created++;}catch(RuntimeException e){errors++;result.addProperty("status","error");result.addProperty("message",e instanceof QualificationService.Problem||e instanceof CourseSectionService.Problem||e instanceof SectionAssignmentService.Problem?e.getMessage():"Invalid row: "+e.getClass().getSimpleName());}results.add(result);}
  JsonObject report=new JsonObject();report.add("rows",results);report.addProperty("errors",errors);report.addProperty("createdRows",created);report.addProperty("unchangedRows",skipped);report.addProperty("canImport",errors==0&&!rows.isEmpty());report.addProperty("previewToken",stamp);report.addProperty("committed",false);
  if(commit){if(errors>0||rows.isEmpty())throw problem("Import rejected: fix all preview errors first. No records were saved.");data.replaceImportedData(ds);data.addLog("CSV Import","info",user.getName(),actor,"Imported "+kind+": "+created+" created rows; "+skipped+" unchanged rows; cycle "+p.getId(),"127.0.0.1");report.addProperty("committed",true);}return report;
 }
 private Module module(DataStore ds,ApplicationPeriod p,String code){List<Module> all=ds.getModules().stream().filter(m->code.equalsIgnoreCase(m.getCode())).toList();String term=ds.getTerms().stream().filter(t->p.getTermId().equals(t.getId())).map(Term::getName).findFirst().orElse("");List<Module> same=all.stream().filter(m->Objects.equals(term,m.getTerm())).toList();if(same.size()==1)return same.get(0);if(all.size()==1)return all.get(0);if(all.isEmpty())return null;throw problem("Ambiguous Course ID: "+code);}
 private String course(JsonDataService d,User actor,JsonObject options,ApplicationPeriod p,Map<String,String> r){DataStore ds=d.getData();String code=need(r,"Course ID"),name=need(r,"Course Name");if(code.length()>100||name.length()>200)throw problem("Course ID/name is too long.");Module m=module(ds,p,code);
  User owner="organiser".equals(actor.getRole())?actor:ds.getUsers().stream().filter(u->text(options,"organiserId").equals(u.getId())&&"organiser".equals(u.getRole())&&"active".equals(u.getStatus())).findFirst().orElseThrow(()->problem("Choose an active course organiser for imported courses."));
  if(m==null){m=new Module();m.setId(id("module_"));m.setCode(code);m.setName(name);m.setDepartment(text(options,"department"));m.setOrganiserId(owner.getId());m.setOrganiserName(owner.getName());m.setStatus("active");m.setTerm(ds.getTerms().stream().filter(t->p.getTermId().equals(t.getId())).map(Term::getName).findFirst().orElse(""));ds.getModules().add(m);}else if(!"admin".equals(actor.getRole())&&!actor.getId().equals(m.getOrganiserId()))throw new QualificationService.Problem(403,"Course is not assigned to you: "+code);
  if(!m.getName().equals(name))throw problem("Existing Course ID has a different course name. Resolve it before import.");String sectionName=need(r,"Section Type");JsonObject b=new JsonObject();b.addProperty("periodId",p.getId());b.addProperty("name",sectionName);String type=sectionName.toLowerCase(Locale.ROOT).startsWith("lab")?"lab":sectionName.toLowerCase(Locale.ROOT).startsWith("discussion")?"discussion":"lecture";if(!sectionName.toLowerCase(Locale.ROOT).matches("(lecture|discussion.*|lab.*)"))throw problem("Unknown section type.");b.addProperty("type",type);b.addProperty("timeZone",AvailabilityService.TIME_ZONE);b.add("meetingTimes",JsonUtil.getGson().toJsonTree(parseSchedule(need(r,"Section Schedule (Days/Time)"))));
  try{b.addProperty("taPositions",Integer.parseInt(need(r,"Positions Needed")));}catch(NumberFormatException e){throw problem("Positions Needed must be a whole number.");}
  if(!options.has("hoursPerWeek"))throw problem("Specify hours per TA per week; the course CSV does not provide them.");b.add("hoursPerWeek",b.get("taPositions").getAsInt()==0?new JsonPrimitive(0):options.get("hoursPerWeek"));b.addProperty("facultyName",m.getOrganiserName());JsonObject c=criteria(split(r.get("Required Skills")),split(r.get("Preferred Skills")));b.add("matchingCriteria",c);
  Module course=m;CourseSection prior=ds.getCourseSections().stream().filter(s->course.getId().equals(s.getModuleId())&&p.getId().equals(s.getPeriodId())&&s.getName().equalsIgnoreCase(sectionName)).findFirst().orElse(null);
  if(prior!=null){if(prior.getTaPositions()==b.get("taPositions").getAsInt()&&prior.getHoursPerWeek()==b.get("hoursPerWeek").getAsDouble()&&JsonUtil.getGson().toJsonTree(prior.getMeetingTimes()).equals(b.get("meetingTimes"))&&prior.getMatchingCriteria()!=null&&prior.getMatchingCriteria().get("requiredSkills").equals(c.get("requiredSkills"))&&prior.getMatchingCriteria().get("preferredSkills").equals(c.get("preferredSkills")))return "unchanged";throw problem("Section already exists with different data. Use its edit screen or a new cycle.");}
  new CourseSectionService(d).create(actor.getId(),actor.getRole(),m.getId(),b);Job j=job(ds,m,p,true);if(j.getPeriodCriteria()==null)j.setPeriodCriteria(new JsonObject());JsonObject pc=j.getPeriodCriteria().deepCopy();pc.add(p.getId(),criteria(List.of(),List.of()));j.setPeriodCriteria(pc);if(j.getId().startsWith("job_")){String courseId=m.getId();j.setPositions(ds.getCourseSections().stream().filter(s->courseId.equals(s.getModuleId())&&p.getId().equals(s.getPeriodId())&&"active".equals(s.getStatus())).mapToInt(CourseSection::getTaPositions).sum());j.setHoursPerWeek((int)Math.ceil(b.get("hoursPerWeek").getAsDouble()));}return "created";
 }
 public static JsonObject criteria(List<String> required,List<String> preferred){JsonObject c=new JsonObject();c.add("requiredSkills",JsonUtil.getGson().toJsonTree(required.stream().map(SkillCatalogService::canonical).toList()));c.add("preferredSkills",JsonUtil.getGson().toJsonTree(preferred.stream().map(SkillCatalogService::canonical).toList()));for(String key:List.of("subjectInterests","studentLevels","skillOptions"))c.add(key,new JsonArray());c.addProperty("trainingRequired",false);c.addProperty("sexualHarassmentTrainingRequired",false);c.addProperty("teachingExperiencePreferred",false);return CriteriaMatchingService.validate(c);}
 private Job job(DataStore ds,Module m,ApplicationPeriod p,boolean create){List<Job> jobs=ds.getJobs().stream().filter(j->m.getId().equals(j.getModuleId())&&m.getOrganiserId().equals(j.getOrganiserId())).toList();if(jobs.size()==1)return jobs.get(0);if(jobs.size()>1)throw problem("Multiple positions exist for "+m.getCode()+"; choose/resolve the position before import.");if(!create)throw problem("Import courses before student applications: "+m.getCode());Job j=new Job();j.setId(id("job_"));j.setModuleId(m.getId());j.setModuleCode(m.getCode());j.setTitle("Teaching Assistant - "+m.getName());j.setOrganiserId(m.getOrganiserId());j.setProfessor(m.getOrganiserName());j.setDepartment(m.getDepartment());j.setStatus("active");j.setPositions(0);j.setHoursPerWeek(0);j.setDeadline(p.getClosesAt().substring(0,10));j.setDescription("Imported course position. Section-level staffing and skills apply.");j.setCreatedAt(now());j.setTags(new ArrayList<>());j.setRequirements(new ArrayList<>());j.setResponsibilities(new ArrayList<>());ds.getJobs().add(j);return j;}
 public static List<CourseSection.MeetingTime> parseSchedule(String raw){List<CourseSection.MeetingTime> meetings=new ArrayList<>();if(raw.isBlank())return meetings;Map<String,Integer> days=Map.of("mon",1,"tue",2,"wed",3,"thu",4,"fri",5,"sat",6,"sun",7);for(String piece:raw.split(";")){String chunk=piece.replaceFirst("(?i)All Day", "00:00 - 24:00");Matcher match=Pattern.compile("(?i)^\\s*([A-Za-z/ ]+)\\s+(\\d{2}:\\d{2})\\s*[-–]\\s*(\\d{2}:\\d{2})\\s*$").matcher(chunk);if(!match.matches())throw problem("Use schedules such as Mon/Wed 09:00 - 10:20; Fri 14:00 - 15:00.");String start=match.group(2),end=match.group(3);if(!start.matches("(?:[01]\\d|2[0-3]):[0-5]\\d")||!end.matches("(?:[01]\\d|2[0-3]):[0-5]\\d|24:00")||start.compareTo(end)>=0)throw problem("Invalid schedule time range.");for(String day:match.group(1).trim().split("/")){Integer n=days.get(day.trim().toLowerCase(Locale.ROOT));if(n==null)throw problem("Unknown weekday: "+day);CourseSection.MeetingTime m=new CourseSection.MeetingTime();m.setDayOfWeek(n);m.setStartTime(start);m.setEndTime(end);meetings.add(m);}}meetings.sort(Comparator.comparingInt(CourseSection.MeetingTime::getDayOfWeek).thenComparing(CourseSection.MeetingTime::getStartTime));return meetings;}
 private JsonObject studentQualifications(Map<String,String> r,DataStore ds){JsonObject q=new JsonObject();String[][] fields={{"firstName","First Name"},{"lastName","Last Name"},{"uciEmail","UCI Email"},{"uciStudentId","UCI Student ID"},{"program","Academic Program"},{"facultyPI","Faculty/PI"},{"additionalEmployment","Additional On-Campus Employment"},{"schedulingConflicts","Scheduling Conflicts"},{"testingScenario","Testing Scenario / Purpose"}};for(String[] pair:fields)q.addProperty(pair[0],r.get(pair[1]));
  String level=need(r,"Student Level");q.addProperty("studentLevel",switch(level.toLowerCase(Locale.ROOT)){case "phd"->"phd";case "master's","masters","master’s"->"masters";case "undergraduate"->"undergraduate";default->throw problem("Unknown Student Level.");});
  if(!r.get("Year Started Graduate Program").isBlank()&&!r.get("Year Started Graduate Program").toUpperCase(Locale.ROOT).startsWith("N/A"))q.addProperty("graduateStartYear",r.get("Year Started Graduate Program"));q.addProperty("taQuarters",need(r,"Total TA Quarters at UCI"));String advanced=need(r,"Advanced to Candidacy");q.addProperty("advancedToCandidacy",advanced.equalsIgnoreCase("N/A")?"not_applicable":yes(advanced)?"yes":"no");q.addProperty("trainingStatus",yes(r.get("Completed TA Training"))?"completed":"not_started");q.addProperty("sexualHarassmentTrainingCompleted",yes(r.get("Completed Online Sexual Harassment Training")));
  String dsc=need(r,"Documented Accommodation (DSC)");boolean accommodation=dsc.equalsIgnoreCase("Yes")||dsc.toLowerCase(Locale.ROOT).startsWith("yes (");if(!accommodation&&!dsc.equalsIgnoreCase("No"))throw problem("DSC must be Yes, No, or Yes (arrangement note).");q.addProperty("documentedAccommodation",accommodation);q.addProperty("accommodationNotes",accommodation?dsc.replaceFirst("(?i)^Yes\\s*",""):"");
  q.addProperty("ackSchedule",yes(r.get("Ack: Schedule Conflict Check")));q.addProperty("ackEnrollment",yes(r.get("Ack: Full-Time Enrollment & Fees")));q.addProperty("acknowledged",true);
  q.add("skills",JsonUtil.getGson().toJsonTree(split(r.get("Skills & Experience")).stream().map(SkillCatalogService::canonical).map(s->s.startsWith("General Bio (")?"General Bio":s).filter(s->SkillCatalogService.skills(ds).stream().anyMatch(v->v.equalsIgnoreCase(s))).toList()));q.add("interests",JsonUtil.getGson().toJsonTree(split(need(r,"Courses of Interest"))));q.addProperty("additionalComments",r.get("Skills & Experience"));String experience=String.join(", ",split(r.get("Skills & Experience")).stream().filter(s->SkillCatalogService.skills(ds).stream().noneMatch(v->v.equalsIgnoreCase(SkillCatalogService.canonical(s)))).toList());q.addProperty("teachingExperience",!experience.isBlank()?experience:Integer.parseInt(r.get("Total TA Quarters at UCI"))>0?"Previously served "+r.get("Total TA Quarters at UCI")+" TA quarters at UCI (excluding summer).":"");return QualificationService.validate(q);
 }
 private static String fingerprint(JsonObject q){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(q.toString().getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 private String student(JsonDataService d,ApplicationPeriod p,Map<String,String> r){DataStore ds=d.getData();JsonObject q=studentQualifications(r,ds);String email=q.get("uciEmail").getAsString(),sid=q.get("uciStudentId").getAsString();
  List<User> candidates=ds.getUsers().stream().filter(u->email.equalsIgnoreCase(u.getEmail())).toList();User u=candidates.isEmpty()?null:candidates.get(0);if(u!=null&&!"applicant".equals(u.getRole()))throw problem("UCI email belongs to a staff account.");
  String expected=u==null?null:u.getId();for(Profile profile:ds.getProfiles()){JsonObject pq=profile.getQualifications();if(!Objects.equals(expected,profile.getUserId())&&(sid.equals(profile.getStudentId())||pq!=null&&sid.equals(text(pq,"uciStudentId"))))throw problem("Student ID already belongs to a different account.");}
  List<Module> modules=new ArrayList<>();for(JsonElement e:q.getAsJsonArray("interests")){Module m=module(ds,p,e.getAsString());if(m==null)throw problem("Unknown course of interest; import courses first: "+e.getAsString());job(ds,m,p,false);modules.add(m);}if(modules.isEmpty())throw problem("Choose at least one course of interest.");
  String mark=fingerprint(q);if(u!=null){String uid=u.getId();List<Application> old=ds.getApplications().stream().filter(a->uid.equals(a.getApplicantId())&&p.getId().equals(a.getPeriodId())).toList();if(!old.isEmpty()){if(old.size()==modules.size()&&old.stream().allMatch(a->a.getQualificationSnapshot()!=null&&mark.equals(text(a.getQualificationSnapshot(),"importFingerprint"))))return "unchanged";throw problem("Student already has different applications in this cycle. Historical submissions are not overwritten.");}}
  if(u==null){u=new User();u.setId(id("user_"));u.setName(q.get("firstName").getAsString()+" "+q.get("lastName").getAsString());u.setEmail(email);u.setRole("applicant");u.setStatus("suspended");u.setDepartment(q.get("program").getAsString());u.setPassword(PasswordSecurity.hash(UUID.randomUUID().toString()));u.setCreatedAt(now());ds.getUsers().add(u);}
  String uid=u.getId();Profile profile=ds.getProfiles().stream().filter(v->uid.equals(v.getUserId())).findFirst().orElse(null);if(profile==null){profile=new Profile();profile.setId(id("profile_"));profile.setUserId(uid);profile.setDocuments(new ArrayList<>());profile.setSkills(new ArrayList<>());profile.setCoursework(new ArrayList<>());profile.setExperience(new ArrayList<>());profile.setMaxWeeklyHours(20);profile.setMaxGpa(4);ds.getProfiles().add(profile);}profile.setStudentId(sid);profile.setDegree(q.get("program").getAsString());profile.setQualifications(q.deepCopy());
  WeeklyAvailability availability=new WeeklyAvailability();availability.setId(id("availability_"));availability.setApplicantId(uid);availability.setPeriodId(p.getId());availability.setTimeZone(AvailabilityService.TIME_ZONE);availability.setConflictsOnly(true);availability.setNotes("[CSV conflicts only] Full availability has not been confirmed.");availability.setUpdatedAt(now());availability.setAvailableSlots(new ArrayList<>());availability.setConflictSlots(new ArrayList<>());
  for(CourseSection.MeetingTime m:parseSchedule(r.get("Scheduling Conflicts"))){WeeklyAvailability.Slot slot=new WeeklyAvailability.Slot();slot.setDayOfWeek(m.getDayOfWeek());slot.setStartTime(m.getStartTime());slot.setEndTime(m.getEndTime());slot.setReason("Reported scheduling conflict");availability.getConflictSlots().add(slot);}
  ds.getWeeklyAvailabilities().removeIf(a->uid.equals(a.getApplicantId())&&p.getId().equals(a.getPeriodId()));ds.getWeeklyAvailabilities().add(availability);
  JsonObject snap=q.deepCopy();snap.addProperty("fullName",q.get("firstName").getAsString()+" "+q.get("lastName").getAsString());snap.addProperty("submittedAt",now());snap.addProperty("importFingerprint",mark);JsonObject academic=JsonUtil.getGson().toJsonTree(profile).getAsJsonObject();academic.remove("qualifications");snap.add("academicProfile",academic);
  for(Module m:modules){Application a=new Application();a.setId(id("application_"));a.setApplicantId(uid);a.setPeriodId(p.getId());a.setJobId(job(ds,m,p,false).getId());a.setStatus("applied");a.setCoverLetter("Imported CSV application");a.setDocumentIds(new ArrayList<>());a.setQualificationSnapshot(snap.deepCopy());a.setAvailabilitySnapshot(JsonUtil.getGson().fromJson(JsonUtil.getGson().toJson(availability),WeeklyAvailability.class));a.setAppliedAt(now());a.setUpdatedAt(now());a.setTimeline(new ArrayList<>());ds.getApplications().add(a);}return "created";
 }
 private String selection(JsonDataService d,User actor,ApplicationPeriod p,Map<String,String> r){DataStore ds=d.getData();String first=need(r,"First Name"),last=need(r,"Last Name");Set<String> users=new HashSet<>();for(Application a:ds.getApplications())if(p.getId().equals(a.getPeriodId())&&a.getQualificationSnapshot()!=null&&first.equalsIgnoreCase(text(a.getQualificationSnapshot(),"firstName"))&&last.equalsIgnoreCase(text(a.getQualificationSnapshot(),"lastName")))users.add(a.getApplicantId());if(users.size()!=1)throw problem("Applicant name is missing or ambiguous; resolve by student ID before import.");
  String proposal=need(r,"Proposed Course & Section");int separator=proposal.indexOf(" - ");if(separator<0)throw problem("Use Course ID - Section Type.");Module m=module(ds,p,proposal.substring(0,separator).trim());if(m==null)throw problem("Course does not exist.");String sectionName=proposal.substring(separator+3).trim();List<CourseSection> sections=ds.getCourseSections().stream().filter(s->m.getId().equals(s.getModuleId())&&p.getId().equals(s.getPeriodId())&&norm(s.getName()).equals(norm(sectionName))).toList();if(sections.size()!=1)throw problem("Proposed section is missing or ambiguous.");CourseSection section=sections.get(0);
  List<Application> applications=ds.getApplications().stream().filter(a->users.contains(a.getApplicantId())&&p.getId().equals(a.getPeriodId())&&ds.getJobs().stream().anyMatch(j->a.getJobId().equals(j.getId())&&m.getId().equals(j.getModuleId()))).toList();if(applications.size()!=1)throw problem("Student has no unique application to this course.");Application app=applications.get(0);String action=switch(need(r,"Selection Status").toLowerCase(Locale.ROOT)){case "selected"->"approve";case "proposed"->"recommend";case "flagged"->"flag";case "rejected"->"not_selected";case "alternate"->"alternate";default->throw problem("Unknown Selection Status.");};
  String mark=fingerprint(JsonUtil.getGson().toJsonTree(r).getAsJsonObject());for(ReviewRecord v:ds.getReviewRecords())if(app.getId().equals(v.getApplicationId())&&section.getId().equals(v.getSectionId())&&v.getSourceMetadata()!=null&&v.getSourceMetadata().isJsonObject()&&mark.equals(text(v.getSourceMetadata().getAsJsonObject(),"fingerprint")))return "unchanged";
  JsonObject body=new JsonObject();body.addProperty("action",action);body.addProperty("sectionId",section.getId());body.addProperty("note","CSV selection import: "+need(r,"Conflict/Eligibility Notes"));new ReviewService(d).record(actor.getId(),app.getId(),body);ReviewRecord record=ds.getReviewRecords().get(ds.getReviewRecords().size()-1);JsonObject meta=new JsonObject();meta.addProperty("fingerprint",mark);meta.addProperty("responsibleUser",r.get("Responsible User"));meta.addProperty("matchStatus",r.get("Match Status"));meta.addProperty("rosterPreview",r.get("Export Roster Preview"));record.setSourceMetadata(meta);return "created";
 }
 private boolean permitted(DataStore ds,User u,Job j){return ds.getModules().stream().anyMatch(m->j.getModuleId().equals(m.getId())&&ReviewAccess.course(u,m));}
 public String export(String actor,String kind,String periodId,boolean template){headers(kind);DataStore ds=data.getData();User u=ReviewAccess.user(ds,actor);if(!"applicant".equals(u.getRole())&&!ReviewAccess.can(u,"review.read"))throw new QualificationService.Problem(403,"Review read permission is required.");if("applicant".equals(u.getRole())&&!"students".equals(kind))throw new QualificationService.Problem(403,"Students may export only their own applications.");if(template)return SponsorCsv.write(headers(kind),List.of());
  period(ds,periodId);List<List<String>> rows=new ArrayList<>();Set<String> seen=new HashSet<>();
  if("courses".equals(kind)){for(CourseSection s:ds.getCourseSections())if(periodId.equals(s.getPeriodId())&&"active".equals(s.getStatus())){Module m=ds.getModules().stream().filter(v->s.getModuleId().equals(v.getId())).findFirst().orElseThrow();if(!ReviewAccess.course(u,m))continue;JsonObject c=s.getMatchingCriteria();rows.add(List.of(m.getCode(),m.getName(),s.getName(),formatSchedule(s.getMeetingTimes()),""+s.getTaPositions(),list(c,"requiredSkills"),list(c,"preferredSkills")));}}
  else for(Application a:ds.getApplications().stream().sorted(Comparator.comparing(Application::getAppliedAt,Comparator.nullsFirst(Comparator.naturalOrder())).reversed()).toList()){if(!periodId.equals(a.getPeriodId()))continue;Job j=ds.getJobs().stream().filter(v->a.getJobId().equals(v.getId())).findFirst().orElse(null);if(j==null||("applicant".equals(u.getRole())?!u.getId().equals(a.getApplicantId()):!permitted(ds,u,j)))continue;JsonObject q=a.getQualificationSnapshot();if(q==null)continue;
   if("students".equals(kind)){if(!seen.add(a.getApplicantId()))continue;rows.add(studentRow(q));}
   else{Map<String,ReviewRecord> latest=new LinkedHashMap<>();for(ReviewRecord v:ds.getReviewRecords())if(a.getId().equals(v.getApplicationId())&&v.getSectionId()!=null&&Set.of("approve","recommend","flag","not_selected","alternate").contains(v.getAction())){ReviewRecord previous=latest.get(v.getSectionId());if(previous==null||!Set.of("approve","not_selected").contains(previous.getAction())||Set.of("approve","not_selected").contains(v.getAction()))latest.put(v.getSectionId(),v);}for(ReviewRecord v:latest.values()){CourseSection s=ds.getCourseSections().stream().filter(x->v.getSectionId().equals(x.getId())).findFirst().orElse(null);if(s!=null){rows.add(selectionRow(ds,u,a,j,s,v));seen.add(a.getId()+s.getId());}}for(SectionAssignment assignment:ds.getSectionAssignments())if(a.getId().equals(assignment.getApplicationId())&&seen.add(a.getId()+assignment.getSectionId()))rows.add(selectionRow(ds,u,a,j,assignment.getSectionSnapshot(),null));}
  }return SponsorCsv.write(headers(kind),rows);
 }
 private List<String> studentRow(JsonObject q){String level=switch(text(q,"studentLevel")){case "phd"->"PhD";case "masters"->"Master's";case "undergraduate"->"Undergraduate";default->"";};return Arrays.asList(text(q,"firstName"),text(q,"lastName"),text(q,"uciEmail"),text(q,"uciStudentId"),level,text(q,"program"),text(q,"graduateStartYear"),text(q,"facultyPI"),text(q,"taQuarters"),text(q,"advancedToCandidacy").isBlank()?"":text(q,"advancedToCandidacy").equals("not_applicable")?"N/A":text(q,"advancedToCandidacy").equals("yes")?"Yes":"No",text(q,"trainingStatus").isBlank()?"":text(q,"trainingStatus").equals("completed")?"Yes":"No",yn(q,"sexualHarassmentTrainingCompleted"),text(q,"additionalEmployment"),yn(q,"documentedAccommodation").isBlank()?"":"Yes".equals(yn(q,"documentedAccommodation"))?"Yes"+(text(q,"accommodationNotes").isBlank()?"":" "+text(q,"accommodationNotes")):"No",yn(q,"ackSchedule"),yn(q,"ackEnrollment"),skillsExperience(q),list(q,"interests"),text(q,"schedulingConflicts"),text(q,"testingScenario"));}
 private static String skillsExperience(JsonObject q){String value=list(q,"skills");if(!text(q,"teachingExperience").isBlank())value+=(value.isBlank()?"":", ")+text(q,"teachingExperience");if(!text(q,"researchExperience").isBlank())value+=(value.isBlank()?"":", ")+"Research: "+text(q,"researchExperience");return value;}
 private static String yn(JsonObject q,String key){return q.has(key)&&!q.get(key).isJsonNull()?(q.get(key).getAsBoolean()?"Yes":"No"):"";}
 private static String list(JsonObject q,String key){if(q==null||!q.has(key)||!q.get(key).isJsonArray())return "";List<String> result=new ArrayList<>();q.getAsJsonArray(key).forEach(e->result.add(e.getAsString()));return String.join(", ",result);}
 public static String formatSchedule(List<CourseSection.MeetingTime> meetings){if(meetings==null)return "";List<String> rows=new ArrayList<>();String[] days={"","Mon","Tue","Wed","Thu","Fri","Sat","Sun"};for(CourseSection.MeetingTime m:meetings)rows.add(days[m.getDayOfWeek()]+" "+m.getStartTime()+" - "+m.getEndTime());return String.join("; ",rows);}
 private List<String> selectionRow(DataStore ds,User viewer,Application a,Job j,CourseSection section,ReviewRecord v){JsonObject q=a.getQualificationSnapshot();JsonObject qualifications=new CriteriaMatchingService().evaluate(a,j,section);JsonObject schedule=new SectionMatchingService().match(ds,a,j,j.getOrganiserId());String time="pending";for(JsonElement row:schedule.getAsJsonArray("sections"))if(section.getId().equals(text(row.getAsJsonObject(),"sectionId")))time=text(row.getAsJsonObject(),"status");String match="conflict".equals(time)?"Conflict Detected":"missing_required".equals(text(qualifications,"status"))?"Unqualified":"pending".equals(time)||"needs_confirmation".equals(text(qualifications,"status"))?"Needs Confirmation":"Matched";
  String status=v==null?"Selected":switch(v.getAction()){case "approve"->"Selected";case "recommend"->"Proposed";case "flag"->"Flagged";case "not_selected"->"Rejected";default->"Alternate";};String notes=match+". "+text(qualifications,"message");if(ReviewAccess.can(viewer,"review.note")&&v!=null)notes+=" | "+v.getNote();String responsible=v==null?"Assignment ledger":ds.getUsers().stream().filter(x->v.getActorId().equals(x.getId())).map(User::getName).findFirst().orElse(v.getActorId());if(v!=null&&v.getSourceMetadata()!=null&&v.getSourceMetadata().isJsonObject()&&!text(v.getSourceMetadata().getAsJsonObject(),"responsibleUser").isBlank())responsible=text(v.getSourceMetadata().getAsJsonObject(),"responsibleUser");String preview=text(q,"firstName")+" "+text(q,"lastName")+" | "+text(q,"uciStudentId")+" | "+j.getModuleCode()+" "+section.getName()+" | "+status;return Arrays.asList(text(q,"firstName"),text(q,"lastName"),j.getModuleCode()+" - "+section.getName(),match,notes,status,responsible,preview);}
}
